        detach(a.finderStage);workspace.addView(a.finderStage,new LinearLayout.LayoutParams(-1,0,1));rail=a.column();controlPane=new ScrollView(a);controlPane.setFillViewport(false);controlPane.setVerticalScrollBarEnabled(false);controlPane.addView(rail,new ScrollView.LayoutParams(-1,-2));workspace.addView(controlPane,new LinearLayout.LayoutParams(-1,-2));
